```json
{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, count(*) AS n_abnormal FROM abnormal_traces WHERE service_name = 'reservation' GROUP BY service_name", "claim": "Reservation service emits zero spans in the abnormal window, versus about 1574 in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE 'reservation.Reservation/%' GROUP BY ALL", "claim": "Frontend's reservation client calls all fail with Error in about 0.01 ms, i.e. immediate refusal, not slow responses."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY ALL", "claim": "Frontend logs 342 'Reservation check availability failed' and 6 'Reservation failed' errors in the abnormal window."},
        {"kind": "metric", "sql": "SELECT metric, service_name, attr_k8s_pod_name, min(time) t0, max(time) t1, count(*) n FROM abnormal_metrics_sum WHERE service_name='reservation' GROUP BY ALL", "claim": "No reservation pod metrics appear in the abnormal window; the normal-period pod stopped reporting at 03:47."}
      ]
    },
    {
      "service": "search",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, avg(value) cpu FROM abnormal_metrics WHERE service_name='search' AND metric='container.cpu.usage' GROUP BY 1 ORDER BY 1", "claim": "Search container CPU pinned at about 2.5 cores from 03:48 onward, versus about 0.006 cores in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name='search.Search/Nearby' GROUP BY ALL", "claim": "Frontend's client calls to search have a median of about 3.6 ms in the abnormal window, up from about 2.6 ms in normal."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','reservation.Reservation/CheckAvailability') GROUP BY ALL", "claim": "All 718 frontend /hotels server spans end in Error, with status 500 on the reservation path, after reservation calls fail."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, count(*) n FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Search's server spans are slower at the median (about 3.6 ms) while frontend's calls into search also slow."}
      ]
    }
  ]
}
